"use strict";(globalThis.webpackChunkjc_community_site=globalThis.webpackChunkjc_community_site||[]).push([[66747],{44547(e,s,n){n.r(s),n.d(s,{assets:()=>l,contentTitle:()=>a,default:()=>d,frontMatter:()=>i,metadata:()=>t,toc:()=>u});const t=JSON.parse('{"id":"general/onboarding-script-report-for-each-system-the-users-it-has-and-if","title":"Onboarding Script Report For Each System The Users It Has And If","description":"By Idan","source":"@site/docs/general/onboarding-script-report-for-each-system-the-users-it-has-and-if.md","sourceDirName":"general","slug":"/general/onboarding-script-report-for-each-system-the-users-it-has-and-if","permalink":"/jc-community-archive/general/onboarding-script-report-for-each-system-the-users-it-has-and-if","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Onboarding Script Report For Each System The Users It Has And If","description":"By Idan"},"sidebar":"docs","previous":{"title":"Onboarding Our First It Employee","permalink":"/jc-community-archive/general/onboarding-our-first-it-employee"},"next":{"title":"Onboarding With Jumpcloud User Welcome Sheet","permalink":"/jc-community-archive/general/onboarding-with-jumpcloud-user-welcome-sheet"}}');var o=n(74848),r=n(28453);const i={title:"Onboarding Script Report For Each System The Users It Has And If",description:"By Idan"},a=void 0,l={},u=[];function m(e){const s={code:"code",p:"p",pre:"pre",...(0,r.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(s.p,{children:"Today I had a conversation with a new JumpCloud customer, and they raised an issue they have to optimize their JumpCloud onboarding project (i.e., deploying JumpCloud across their entire company, which is significant in size)."}),"\n",(0,o.jsx)(s.p,{children:"The ask was to know the users on each system (aka device) and whether JumpCloud manages them. Going to the current JumpCloud reports would be less helpful in this case, as these reports show each User the systems bound to it. In this scenario, we want the exact opposite."}),"\n",(0,o.jsx)(s.p,{children:'This use case was very interesting, so I decided to script and share it with the JumpCloud community. My approach was to get all users from "System Insights" and cross reference that with all "Systems". In SQL terms, this is a Left-Outer Join between "Systems" (on the left) and "System Insights Users" (on the right), where the join is on the SystemId. I\'m using a Left-Outer Join because we are looking at this from the device perspective, and some devices may have no users on them. From there, I decided to change the names of the fields to be more consistent and friendly to new JumpCloud customers unfamiliar with our API.'}),"\n",(0,o.jsx)(s.p,{children:'The script returns a summary to your console about interactive (real/human) users and the systems in your environment, two output files: one in CSV, which you can use in Google Sheets/Excel/etc., and a JSON file you can process however else you want. The output files also have a field named " systemJumpCloudDetails" that contains an HTTPS link to the device in your JumpCloud console (this is useful for processing systematically).'}),"\n",(0,o.jsx)(s.p,{children:'You can copy paste the script in this post to a file named "all_users_on_devices.ps1" and use it to create your reports.'}),"\n",(0,o.jsx)(s.p,{children:"The generated report is also helpful for compliance purposes, as non-managed users are visible even if they are admins. For example, in a scenario where there are users with Admin privileges but not IT staff (such as R&D employees), it is essential to know if other local users appear on a device and what their privileges are. Pushing the report to a versioning system allows monitoring of such changes for compliance and auditing."}),"\n",(0,o.jsx)(s.p,{children:"Happy New Year to all !"}),"\n",(0,o.jsx)(s.p,{children:"DISCLAIMER:"}),"\n",(0,o.jsx)(s.p,{children:"a. JUMPCLOUD DOES NOT PROVIDE SUPPORT FOR THIS SCRIPT"}),"\n",(0,o.jsx)(s.p,{children:"b. THIS SCRIPT IS PROVIDED AS-IS WITH NO WARRANTY OR GUARANTEE"}),"\n",(0,o.jsx)(s.p,{children:"c. USE THIS SCRIPT ON YOUR DISCRETION"}),"\n",(0,o.jsx)(s.p,{children:"d. YOU MAY USE THIS SCRIPT FOR TESTING, LEARNING, AND INSPIRATION"}),"\n",(0,o.jsx)(s.pre,{children:(0,o.jsx)(s.code,{children:"<# \n# THIS SCRIPT WAS CREATED BY IDAN MASHAAL\n# NAME OF SCRIPT: 'all_users_on_devices.ps1'\n#\n# 1. DISCLAIMER:\n#    a. JUMPCLOUD DOES NOT PROVIDE SUPPORT FOR THIS SCRIPT\n#    b. THIS SCRIPT IS PROVIDED AS-IS WITH NO WARRANTY OR GUARANTEE\n#    c. USE THIS SCRIPT ON YOUR DISCRETION\n#    d. YOU MAY USE THIS SCRIPT FOR TESTING, LEARNING, AND INSPIRATION\n#\n# 2. Purpose: Reports for all systems and all the users that exist on them, \n# regardless if they are managed or unmanaged by JumpCloud. Using such\n# a report may be helpful when starting a new JumpCloud project deployment.\n#\n# 3. How is this achieved? By retrieving all JumpCloud Systems and all users from System Insights\n# and doing a Left Join from Systems to Users because some systems may not have users.\n# \n# 4. What is the Output?\n#    a. Summary printed to default output (usually the console)\n#    b. Report in CSV file format\n#    c. Report JSON file format \n#    d. Both reports contian the field 'systemJumpCloudDetails' which is a HTTPS link to the system in the JumpCloud console\n#    e. Script performance (duration) depends on the number of systems and users in your environment\n#\n# 5. Requirements:\n#    a. The 'JumpCloud' Powershell Module. (you can use this script to install the module, modify $psmodule_install_if_missing)\n#    b. The 'JoinObject' Powershell Module. (you can use this script to install the module, modify $psmodule_install_if_missing)\n#    c. JumpCloud API Key (read-only preferred)\n# \n#>\n###################### Global Configuration - Start ######################\n$jc_api_key = 'YOUR_JUMPCLOUD_API_KEY_HERE'\n$report_file_name_prefix = 'report_all_users_on_devices'\n$psmodule_install_if_missing = $false\n$psmodule_install_scope = 'CurrentUser'\n####################### Global Configuration - End #######################\n\n################ DO NOT CHANGE ANY LINES BELOW THIS LINE! ################\n\n##### START OF SCRIPT #####\n\n## Install modules if not installed\nif ( $psmodule_install_if_missing )\n{\n    ## Install JumpCloud Module in configured scope if not installed\n    if ( -not (Get-InstalledModule JumpCloud -ErrorAction SilentlyContinue) )\n    {\n        Install-Module JumpCloud -Scope $psmodule_install_scope -Force\n    }\n\n    ## Install JoinModule Module in configured scope if not installed\n    if ( -not (Get-InstalledModule JoinModule -ErrorAction SilentlyContinue) )\n    {\n        Install-Module JoinModule -Scope $psmodule_install_scope -Force\n    }\n}\n\n## Import Modules\nImport-Module JumpCloud\nImport-Module JumpCloud.SDK.V1\nImport-Module JumpCloud.SDK.V2\nImport-Module JumpCloud.SDK.DirectoryInsights\nImport-Module JoinModule -DisableNameChecking\n\n## Connect to JumpCloud\nConnect-JCOnline -JumpCloudApiKey $jc_api_key -Force\n$timestamp_utc = $(((get-date).ToUniversalTime()).ToString(\"yyyyMMdd_HHmmss\"))\n$report_file_name = ($report_file_name_prefix + '-' + $timestamp_utc)\n\n## Get All System Insights (si) Users\n$jc_si_users = Get-JcSdkSystemInsightUser\n\n## Get All JumpCloud Systems\n$jc_systems = Get-JCSystem\n\n## Left-Join between Systems and Devices because we can have devices that have no users\n$jc_system_users = $jc_systems | LeftJoin $jc_si_users -On _id -Equals SystemId \n\n## Make output human readable even without prior JumpCloud knowledge\n$result_field_names = @(\n    @{Name='systemJumpCloudId'; Expression='SystemId'},\n    @{Name='systemHostName'; Expression='hostname'},\n    @{Name='systemJumpCloudDisplayName'; Expression='displayName'},\n    @{Name='systemOs'; Expression='os'},\n    @{Name='osFamily'; Expression='osFamily'},\n    @{Name='osVersion'; Expression='version'},\n    @{Name='osArch'; Expression='arch'},\n    @{Name='systemAgentVersion'; Expression='agentVersion'},\n    @{Name='systemRemoteIp'; Expression='remoteIp'},\n    @{Name='isSystemOnline'; Expression='active'},\n    @{Name='localUserName'; Expression='Username'},\n    @{Name='isUserAdmin'; Expression='Admin'},\n    @{Name='isUserReal'; Expression='RealUser'},\n    @{Name='isUserManagedByJumpCloud'; Expression='Managed'},\n    @{Name='isUserManagedByActiveDirectory'; Expression='AdManaged'},\n    @{Name='systemInsightsCollectionTime'; Expression='CollectionTime'}\n    @{Name='systemJumpCloudDetails'; Expression={\"https://console.jumpcloud.com/#/devices/$($_.SystemId)/details\"}}\n)\n$result = $jc_system_users | Select-Object -Property $result_field_names\n\n## Output Report Results\n$jc_unmanaged_real_users = $result | Where-Object -Property isUserReal -EQ $true | Where-Object -Property isUserManagedByJumpCloud -EQ $false | Measure-Object | Select-Object -ExpandProperty Count\n$jc_managed_real_users = $result | Where-Object -Property isUserManagedByJumpCloud -EQ $true | Measure-Object | Select-Object -ExpandProperty Count\n\n#$result | Format-Table *\n\nWrite-Output (\"`n----------------------------------------------------------------------------------\")\nWrite-Output (\"All Users on All Devices Report for UTC timestamp: \" + $timestamp_utc)\nWrite-Output (\"* Number of Systems: \" + $jc_systems.Count)\nWrite-Output (\"* Number of joined records between all systems and all users: \" + $result.Count)\nWrite-Output (\"* Number of JumpCloud managed real (interactive) users on all systems: \" + $jc_managed_real_users)\nWrite-Output (\"* Number of unmanaged real (interactive) users on all systems: \" + $jc_unmanaged_real_users)\n\n## Store Results to the same folder as the script in csv\n$result | Export-Csv -Path ($report_file_name + '.csv')\nWrite-Output (\"* CSV Report File Name: \" + \"'\" + $report_file_name + \".csv\" + \"'\")\n\n## Store Results to the same folder as the script in csv\n$result | ConvertTo-Json | Out-File -FilePath ($report_file_name + '.json')\nWrite-Output (\"* JSON Report File Name: \" + \"'\" + $report_file_name  + \".json\" + \"'\")\nWrite-Output (\"----------------------------------------------------------------------------------`n\")\n##### END OF SCRIPT #####\n"})})]})}function d(e={}){const{wrapper:s}={...(0,r.R)(),...e.components};return s?(0,o.jsx)(s,{...e,children:(0,o.jsx)(m,{...e})}):m(e)}},28453(e,s,n){n.d(s,{R:()=>i,x:()=>a});var t=n(96540);const o={},r=t.createContext(o);function i(e){const s=t.useContext(r);return t.useMemo(function(){return"function"==typeof e?e(s):{...s,...e}},[s,e])}function a(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),t.createElement(r.Provider,{value:s},e.children)}}}]);